tape( 'the function throws an error if provided an invalid `LDC`', function test( t ) {
	var values;
	var data;
	var i;

	data = LEFT_TRANS_FORWARD_COL_ROW_MAJOR;

	values = [ 0, 1, 2 ];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badRow( values[ i ] ), RangeError, 'row-major throws when provided ' + values[ i ] );
		t.throws( badCol( values[ i ] ), RangeError, 'column-major throws when provided ' + values[ i ] );
	}
	t.end();

	function badRow( value ) {
		return function badRow() {
			dlarfb( data.order, data.side, data.trans, data.direct, 'columns', data.M, data.N, data.K, new Float64Array( data.V ), data.LDV, new Float64Array( data.T ), data.LDT, new Float64Array( data.C ), value, new Float64Array( data.work ), data.LDWORK );
		};
	}

	function badCol( value ) {
		return function badCol() {
			dlarfb( data.order, data.side, data.trans, data.direct, 'columns', data.M, data.N, data.K, new Float64Array( data.V ), data.LDV, new Float64Array( data.T ), data.LDT, new Float64Array( data.C ), value, new Float64Array( data.work ), data.LDWORK );
		};
	}
});

